const Q_R_ABERTAS_ATRASOS = [
  ["Parte II · Atrasos", "A-E5a", "<b>Ficha 1, Ex. 5 — Atrasos & companhia.</b> A e B estão a 10 000 km, com uma ligação direta de R = 1 Mbps e propagação a 2,5×10<sup>8</sup> m/s. Envia-se um ficheiro de 400 000 bits como um pacote único.<br><br>(a) Calcula o atraso de transmissão d<sub>trans</sub>.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">d = 10\\,000</annotation></semantics></math> km <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><msup><mn>10</mn><mn>7</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 10^7</annotation></semantics></math> m; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2{,}5\\times10^8</annotation></semantics></math> m/s; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>400</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">L = 400\\,000</annotation></semantics></math> bits.</p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>t</mi><mi>r</mi><mi>a</mi><mi>n</mi><mi>s</mi></mrow></msub><mo>=</mo><mfrac><mi>L</mi><mi>R</mi></mfrac><mo>=</mo><mfrac><mrow><mn>4</mn><mo>×</mo><msup><mn>10</mn><mn>5</mn></msup></mrow><msup><mn>10</mn><mn>6</mn></msup></mfrac><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟎</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟒</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">d_{trans} = \\frac{L}{R} = \\frac{4\\times10^5}{10^6} = \\mathbf{0{,}4\\text{ s}}</annotation></semantics></math></p>\n</div>", "<b>Para lembrar:</b> d<sub>trans</sub> = L/R.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#as-quatro-fontes-de-atraso\" target=\"_blank\">📖 As quatro fontes de atraso</a>"],
  ["Parte II · Atrasos", "A-E5b", "<b>Ficha 1, Ex. 5 — Atrasos & companhia.</b> A e B estão a 10 000 km, com uma ligação direta de R = 1 Mbps e propagação a 2,5×10<sup>8</sup> m/s. Envia-se um ficheiro de 400 000 bits como um pacote único.<br><br>(b) Calcula o atraso de propagação d<sub>prop</sub>.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">d = 10\\,000</annotation></semantics></math> km <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><msup><mn>10</mn><mn>7</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 10^7</annotation></semantics></math> m; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2{,}5\\times10^8</annotation></semantics></math> m/s; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>400</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">L = 400\\,000</annotation></semantics></math> bits.</p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo>=</mo><mfrac><mi>d</mi><mi>v</mi></mfrac><mo>=</mo><mfrac><msup><mn>10</mn><mn>7</mn></msup><mrow><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow></mfrac><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟎</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟎𝟒</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow><mo mathvariant=\"bold\">=</mo><mn mathvariant=\"bold\">𝟒𝟎</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐦𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">d_{prop} = \\frac{d}{v} = \\frac{10^7}{2{,}5\\times10^8} = \\mathbf{0{,}04\\text{ s} = 40\\text{ ms}}</annotation></semantics></math></p>\n</div>", "<b>Para lembrar:</b> d<sub>prop</sub> = d/v.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#as-quatro-fontes-de-atraso\" target=\"_blank\">📖 As quatro fontes de atraso</a>"],
  ["Parte II · Atrasos", "A-E5c", "<b>Ficha 1, Ex. 5 — Atrasos & companhia.</b> A e B estão a 10 000 km, com uma ligação direta de R = 1 Mbps e propagação a 2,5×10<sup>8</sup> m/s. Envia-se um ficheiro de 400 000 bits como um pacote único.<br><br>(c) Calcula o produto largura de banda–atraso R·d<sub>prop</sub>.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">d = 10\\,000</annotation></semantics></math> km <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><msup><mn>10</mn><mn>7</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 10^7</annotation></semantics></math> m; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2{,}5\\times10^8</annotation></semantics></math> m/s; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>400</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">L = 400\\,000</annotation></semantics></math> bits.</p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>⋅</mo><msub><mi>d</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo>=</mo><msup><mn>10</mn><mn>6</mn></msup><mo>×</mo><mn>0</mn><mo>,</mo><mn>04</mn><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟒𝟎</mn><mspace width=\"0.167em\"></mspace><mn mathvariant=\"bold\">𝟎𝟎𝟎</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐛𝐢𝐭𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">R\\cdot d_{prop} = 10^6 \\times 0{,}04 = \\mathbf{40\\,000\\text{ bits}}</annotation></semantics></math></p>\n</div>", "<b>Para lembrar:</b> R·d<sub>prop</sub> = bits que cabem no cabo.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#débito-throughput\" target=\"_blank\">📖 Débito (throughput)</a>"],
  ["Parte II · Atrasos", "A-E5d", "<b>Ficha 1, Ex. 5 — Atrasos & companhia.</b> A e B estão a 10 000 km, com uma ligação direta de R = 1 Mbps e propagação a 2,5×10<sup>8</sup> m/s. Envia-se um ficheiro de 400 000 bits como um pacote único.<br><br>(d) Qual é o número máximo de bits na ligação num dado instante?", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">d = 10\\,000</annotation></semantics></math> km <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><msup><mn>10</mn><mn>7</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 10^7</annotation></semantics></math> m; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2{,}5\\times10^8</annotation></semantics></math> m/s; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>400</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">L = 400\\,000</annotation></semantics></math> bits.</p>\n<p>É o produto largura de banda–atraso, <strong>40 000 bits</strong>. Ao fim de 40 ms o primeiro bit chega ao destino. Nesse instante já foram emitidos <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>×</mo><mn>40</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ms</mtext></mrow><mo>=</mo><mn>40</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">R \\times 40\\text{ ms} = 40\\,000</annotation></semantics></math> bits, e a partir daí sai um por uma ponta e entra outro pela outra.</p>\n<p>O ficheiro (400 000 bits) é maior do que isto, por isso a ligação chega a estar “cheia”. Em geral o máximo é <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">min</mi><mo>&#8289;</mo></mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>L</mi><mo>,</mo><mspace width=\"0.222em\"></mspace><mi>R</mi><mo>⋅</mo><msub><mi>d</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\min(L,\\ R\\cdot d_{prop})</annotation></semantics></math>.</p>\n</div>", "<b>Para lembrar:</b> o mínimo entre L e R·d<sub>prop</sub>.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#débito-throughput\" target=\"_blank\">📖 Débito (throughput)</a>"],
  ["Parte II · Atrasos", "A-E5e", "<b>Ficha 1, Ex. 5 — Atrasos & companhia.</b> A e B estão a 10 000 km, com uma ligação direta de R = 1 Mbps e propagação a 2,5×10<sup>8</sup> m/s. Envia-se um ficheiro de 400 000 bits como um pacote único.<br><br>(e) Qual é o comprimento, em metros, de um bit na ligação?", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">d = 10\\,000</annotation></semantics></math> km <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><msup><mn>10</mn><mn>7</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 10^7</annotation></semantics></math> m; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2{,}5\\times10^8</annotation></semantics></math> m/s; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>400</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">L = 400\\,000</annotation></semantics></math> bits.</p>\n<p>Um bit ocupa o tempo <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mi>/</mi><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">1/R</annotation></semantics></math>, e nesse tempo o sinal anda <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mi>/</mi><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">v/R</annotation></semantics></math>: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mi>v</mi><mi>R</mi></mfrac><mo>=</mo><mfrac><mrow><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><msup><mn>10</mn><mn>6</mn></msup></mfrac><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟐𝟓𝟎</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐦</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">\\frac{v}{R} = \\frac{2{,}5\\times10^8}{10^6} = \\mathbf{250\\text{ m}}</annotation></semantics></math></p>\n<p>Confirmação: 40 000 bits em 10 000 km dão <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>10</mn><mn>7</mn></msup><mi>/</mi><mn>4</mn><mo>×</mo><msup><mn>10</mn><mn>4</mn></msup><mo>=</mo><mn>250</mn></mrow><annotation encoding=\"application/x-tex\">10^7/4\\times10^4 = 250</annotation></semantics></math> m por bit <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>✓</mi><annotation encoding=\"application/x-tex\">\\checkmark</annotation></semantics></math>.</p>\n</div>", "<b>Para lembrar:</b> comprimento de um bit = v/R.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#débito-throughput\" target=\"_blank\">📖 Débito (throughput)</a>"],
  ["Parte II · Atrasos", "A-E5g", "<b>Ficha 1, Ex. 5 — Atrasos & companhia.</b> A e B estão a 10 000 km, com uma ligação direta de R = 1 Mbps e propagação a 2,5×10<sup>8</sup> m/s. Envia-se um ficheiro de 400 000 bits como um pacote único.<br><br>(g) Dá uma interpretação física do produto largura de banda–atraso.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">d = 10\\,000</annotation></semantics></math> km <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><msup><mn>10</mn><mn>7</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 10^7</annotation></semantics></math> m; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>,</mo><mn>5</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2{,}5\\times10^8</annotation></semantics></math> m/s; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>400</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">L = 400\\,000</annotation></semantics></math> bits.</p>\n<p>É a <strong>“capacidade do tubo”</strong>: quantos bits cabem ao mesmo tempo dentro da ligação, a caminho do destino. Também é quantos bits o emissor tem de pôr na linha até o primeiro chegar ao outro lado.</p>\n<p>Consequência prática, que vai reaparecer no TCP: para usar toda a capacidade de uma ligação, o emissor tem de ter <strong>pelo menos</strong> esse número de bits “em voo” sem esperar confirmação. Se enviar um pacote e ficar à espera da resposta, a ligação fica quase toda vazia. Com 1 Gbps e 10 000 km, o tubo leva 40 Mbit, cerca de 5 MB.</p>\n</div>", "<b>Para lembrar:</b> o cabo como um tubo cheio de bits.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#débito-throughput\" target=\"_blank\">📖 Débito (throughput)</a>"],
  ["Parte II · Atrasos", "A-E4a", "<b>Ficha 1, Ex. 4 — Store and forward.</b> <b>T1 —LAN— R —WAN— T2</b>, em fibra (2×10<sup>8</sup> m/s). LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. Pacotes de 1250 Bytes de T1 para T2; filas vazias e sem outros fluxos.<br><br>(a) Calcula os atrasos de transmissão e de propagação em cada ligação.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>1250</mn></mrow><annotation encoding=\"application/x-tex\">L = 1250</annotation></semantics></math> bytes <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">= 10\\,000</annotation></semantics></math> bits; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2\\times10^8</annotation></semantics></math> m/s. LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. T1 → LAN → R → WAN → T2.</p>\n<table>\n<colgroup>\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n<col style=\"width: 33%\" />\n</colgroup>\n<thead>\n<tr>\n<th style=\"text-align: left;\"></th>\n<th style=\"text-align: left;\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>t</mi><mi>r</mi><mi>a</mi><mi>n</mi><mi>s</mi></mrow></msub><mo>=</mo><mi>L</mi><mi>/</mi><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">d_{trans} = L/R</annotation></semantics></math></th>\n<th style=\"text-align: left;\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>p</mi><mi>r</mi><mi>o</mi><mi>p</mi></mrow></msub><mo>=</mo><mi>d</mi><mi>/</mi><mi>v</mi></mrow><annotation encoding=\"application/x-tex\">d_{prop} = d/v</annotation></semantics></math></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: left;\">LAN</td>\n<td style=\"text-align: left;\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>10</mn><mn>4</mn></msup><mi>/</mi><msup><mn>10</mn><mn>7</mn></msup><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟏</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐦𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">10^4 / 10^7 = \\mathbf{1\\text{ ms}}</annotation></semantics></math></td>\n<td style=\"text-align: left;\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4000</mn><mi>/</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>2</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟐𝟎</mn><mspace width=\"0.222em\"></mspace><mi mathvariant=\"bold-italic\">𝝁</mi><mi mathvariant=\"bold-italic\">𝒔</mi></mrow></mrow><annotation encoding=\"application/x-tex\">4000 / (2\\times10^8) = \\mathbf{20\\ \\mu s}</annotation></semantics></math></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">WAN</td>\n<td style=\"text-align: left;\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>10</mn><mn>4</mn></msup><mi>/</mi><msup><mn>10</mn><mn>9</mn></msup><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟏𝟎</mn><mspace width=\"0.222em\"></mspace><mi mathvariant=\"bold-italic\">𝝁</mi><mi mathvariant=\"bold-italic\">𝒔</mi></mrow></mrow><annotation encoding=\"application/x-tex\">10^4 / 10^9 = \\mathbf{10\\ \\mu s}</annotation></semantics></math></td>\n<td style=\"text-align: left;\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>80</mn><mspace width=\"0.167em\"></mspace><mn>000</mn><mi>/</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>2</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟒𝟎𝟎</mn><mspace width=\"0.222em\"></mspace><mi mathvariant=\"bold-italic\">𝝁</mi><mi mathvariant=\"bold-italic\">𝒔</mi></mrow></mrow><annotation encoding=\"application/x-tex\">80\\,000 / (2\\times10^8) = \\mathbf{400\\ \\mu s}</annotation></semantics></math></td>\n</tr>\n</tbody>\n</table>\n</div>", "<b>Para lembrar:</b> L/R e d/v, em cada ligação.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#as-quatro-fontes-de-atraso\" target=\"_blank\">📖 As quatro fontes de atraso</a>"],
  ["Parte II · Atrasos", "A-E4b", "<b>Ficha 1, Ex. 4 — Store and forward.</b> <b>T1 —LAN— R —WAN— T2</b>, em fibra (2×10<sup>8</sup> m/s). LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. Pacotes de 1250 Bytes de T1 para T2; filas vazias e sem outros fluxos.<br><br>(b) Quanto tempo demora um pacote de T1 a T2 (desde que T1 começa a transmitir até T2 acabar de receber)?", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>1250</mn></mrow><annotation encoding=\"application/x-tex\">L = 1250</annotation></semantics></math> bytes <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">= 10\\,000</annotation></semantics></math> bits; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2\\times10^8</annotation></semantics></math> m/s. LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. T1 → LAN → R → WAN → T2.</p>\n<p>O router tem de receber o pacote todo antes de o reenviar, por isso somam-se as quatro parcelas: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ms</mtext></mrow><mo>+</mo><mn>20</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>+</mo><mn>10</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>+</mo><mn>400</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟏</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟒𝟑</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐦𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">1\\text{ ms} + 20\\ \\mu s + 10\\ \\mu s + 400\\ \\mu s = \\mathbf{1{,}43\\text{ ms}}</annotation></semantics></math></p>\n</div>", "<b>Para lembrar:</b> um pacote: soma trans + prop de cada ligação.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#as-quatro-fontes-de-atraso\" target=\"_blank\">📖 As quatro fontes de atraso</a>"],
  ["Parte II · Atrasos", "A-E4c", "<b>Ficha 1, Ex. 4 — Store and forward.</b> <b>T1 —LAN— R —WAN— T2</b>, em fibra (2×10<sup>8</sup> m/s). LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. Pacotes de 1250 Bytes de T1 para T2; filas vazias e sem outros fluxos.<br><br>(c) Quanto tempo demoram <b>10 pacotes</b> de T1 a T2? Começa por esquematizar num diagrama temporal.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>1250</mn></mrow><annotation encoding=\"application/x-tex\">L = 1250</annotation></semantics></math> bytes <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">= 10\\,000</annotation></semantics></math> bits; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2\\times10^8</annotation></semantics></math> m/s. LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. T1 → LAN → R → WAN → T2.</p>\n<p>A <strong>LAN é o gargalo</strong>: 1 ms por pacote contra 10 µs na WAN.</p>\n<p>Diagrama temporal (instantes em µs, quando cada pacote <strong>acaba</strong> de chegar):</p>\n<table>\n<thead>\n<tr>\n<th style=\"text-align: center;\">pacote</th>\n<th style=\"text-align: center;\">sai de T1</th>\n<th style=\"text-align: center;\">chega a R</th>\n<th style=\"text-align: center;\">sai de R</th>\n<th style=\"text-align: center;\">chega a T2</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: center;\">1</td>\n<td style=\"text-align: center;\">1000</td>\n<td style=\"text-align: center;\">1020</td>\n<td style=\"text-align: center;\">1030</td>\n<td style=\"text-align: center;\">1430</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">2</td>\n<td style=\"text-align: center;\">2000</td>\n<td style=\"text-align: center;\">2020</td>\n<td style=\"text-align: center;\">2030</td>\n<td style=\"text-align: center;\">2430</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">10</td>\n<td style=\"text-align: center;\">10 000</td>\n<td style=\"text-align: center;\">10 020</td>\n<td style=\"text-align: center;\">10 030</td>\n<td style=\"text-align: center;\"><strong>10 430</strong></td>\n</tr>\n</tbody>\n</table>\n<p>O router despacha cada pacote em 10 µs, muito antes de chegar o seguinte (1 ms depois). <strong>Não há fila em R.</strong> O último pacote só sai de T1 aos <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mo>×</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">10 \\times 1</annotation></semantics></math> ms, e depois precisa das mesmas 430 µs do pacote 1: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mo>×</mo><mn>1</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ms</mtext></mrow><mo>+</mo><mn>20</mn><mo>+</mo><mn>10</mn><mo>+</mo><mn>400</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟏𝟎</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟒𝟑</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐦𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">10 \\times 1\\text{ ms} + 20 + 10 + 400\\ \\mu s = \\mathbf{10{,}43\\text{ ms}}</annotation></semantics></math></p>\n</div>", "<b>Para lembrar:</b> a ligação mais lenta dita o ritmo.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#vários-pacotes-e-ligações-em-série\" target=\"_blank\">📖 Vários pacotes e ligações em\nsérie</a>"],
  ["Parte II · Atrasos", "A-E4d", "<b>Ficha 1, Ex. 4 — Store and forward.</b> <b>T1 —LAN— R —WAN— T2</b>, em fibra (2×10<sup>8</sup> m/s). LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. Pacotes de 1250 Bytes de T1 para T2; filas vazias e sem outros fluxos.<br><br>(d) Repete a alínea anterior com LAN de 1 Gb/s e WAN de 10 Mb/s.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>1250</mn></mrow><annotation encoding=\"application/x-tex\">L = 1250</annotation></semantics></math> bytes <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>10</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">= 10\\,000</annotation></semantics></math> bits; <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mn>2</mn><mo>×</mo><msup><mn>10</mn><mn>8</mn></msup></mrow><annotation encoding=\"application/x-tex\">v = 2\\times10^8</annotation></semantics></math> m/s. LAN: 4 km, 10 Mb/s. WAN: 80 km, 1 Gb/s. T1 → LAN → R → WAN → T2.</p>\n<p>Agora <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>d</mi><mrow><mi>t</mi><mi>r</mi><mi>a</mi><mi>n</mi><mi>s</mi></mrow></msub><annotation encoding=\"application/x-tex\">d_{trans}</annotation></semantics></math> na LAN é <strong>10 µs</strong> e na WAN é <strong>1 ms</strong>. As propagações não mudam: 20 µs e 400 µs.</p>\n<ul>\n<li><strong>1 pacote:</strong> <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>10</mn><mo>+</mo><mn>20</mn><mo>+</mo><mn>1000</mn><mo>+</mo><mn>400</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>=</mo><mn>1</mn><mo>,</mo><mn>43</mn></mrow><annotation encoding=\"application/x-tex\">10 + 20 + 1000 + 400\\ \\mu s = 1{,}43</annotation></semantics></math> ms (igual).</li>\n<li><strong>10 pacotes:</strong> os pacotes chegam a R de 10 em 10 µs (o primeiro aos 30 µs), mas a WAN só consegue despachar um por milissegundo. <strong>Forma-se fila em R.</strong></li>\n</ul>\n<table>\n<thead>\n<tr>\n<th style=\"text-align: center;\">pacote</th>\n<th style=\"text-align: center;\">chega a R</th>\n<th style=\"text-align: center;\">começa a sair de R</th>\n<th style=\"text-align: center;\">acaba de sair</th>\n<th style=\"text-align: center;\">chega a T2</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: center;\">1</td>\n<td style=\"text-align: center;\">30</td>\n<td style=\"text-align: center;\">30</td>\n<td style=\"text-align: center;\">1030</td>\n<td style=\"text-align: center;\">1430</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">2</td>\n<td style=\"text-align: center;\">40</td>\n<td style=\"text-align: center;\">1030 (esperou)</td>\n<td style=\"text-align: center;\">2030</td>\n<td style=\"text-align: center;\">2430</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n<td style=\"text-align: center;\">…</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">10</td>\n<td style=\"text-align: center;\">120</td>\n<td style=\"text-align: center;\">9030</td>\n<td style=\"text-align: center;\">10 030</td>\n<td style=\"text-align: center;\"><strong>10 430</strong></td>\n</tr>\n</tbody>\n</table>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>30</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>+</mo><mn>10</mn><mo>×</mo><mn>1</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ms</mtext></mrow><mo>+</mo><mn>400</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟏𝟎</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟒𝟑</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐦𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">30\\ \\mu s + 10 \\times 1\\text{ ms} + 400\\ \\mu s = \\mathbf{10{,}43\\text{ ms}}</annotation></semantics></math></p>\n<p>O tempo total é <strong>o mesmo</strong> da (c). O que manda é a ligação mais lenta, esteja à entrada ou à saída, e ela tem de transmitir os 10 pacotes. O que muda é <strong>onde</strong> os pacotes esperam: na (c) esperam em T1, antes de entrar na LAN; na (d) acumulam-se na <strong>fila do router</strong>. Se a fila de R fosse pequena, na (d) podia haver <strong>perdas</strong>.</p>\n</div>", "<b>Para lembrar:</b> agora a lenta é a WAN: forma-se fila no router.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#vários-pacotes-e-ligações-em-série\" target=\"_blank\">📖 Vários pacotes e ligações em\nsérie</a>"],
  ["Parte II · Atrasos", "A-E3a", "<b>Ficha 1, Ex. 3 — Em pedaços.</b> A Alice envia ao Bob um vídeo de 700 MB. Entre os dois há 2 routers e todas as ligações têm 100 Mbps (<i>store-and-forward</i>: cada nó recebe o bloco todo antes de o reenviar).<br><br>(a) Quanto tempo demora, desde que a Alice começa a enviar o ficheiro inteiro até o Bob o acabar de receber?", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>700</mn></mrow><annotation encoding=\"application/x-tex\">L = 700</annotation></semantics></math> MB <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>5</mn><mo>,</mo><mn>6</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 5{,}6 \\times 10^9</annotation></semantics></math> bits; 2 routers, portanto <strong>3 ligações</strong>, todas a <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">R = 100</annotation></semantics></math> Mbps. Ignoram-se propagação, processamento e filas, porque o enunciado não os dá.</p>\n<p>Cada nó tem de receber o ficheiro todo antes de o reenviar. O tempo de transmissão numa ligação é <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mrow><mi>t</mi><mi>r</mi><mi>a</mi><mi>n</mi><mi>s</mi></mrow></msub><mo>=</mo><mfrac><mi>L</mi><mi>R</mi></mfrac><mo>=</mo><mfrac><mrow><mn>5</mn><mo>,</mo><mn>6</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup></mrow><msup><mn>10</mn><mn>8</mn></msup></mfrac><mo>=</mo><mn>56</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> s</mtext></mrow></mrow><annotation encoding=\"application/x-tex\">d_{trans} = \\frac{L}{R} = \\frac{5{,}6\\times10^9}{10^8} = 56\\text{ s}</annotation></semantics></math></p>\n<p>Há três ligações em série e cada uma só começa quando a anterior acaba: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3</mn><mo>×</mo><mn>56</mn><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟏𝟔𝟖</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">3 \\times 56 = \\mathbf{168\\text{ s}}</annotation></semantics></math></p>\n</div>", "<b>Para lembrar:</b> ficheiro inteiro: cada ligação espera pela anterior.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#vários-pacotes-e-ligações-em-série\" target=\"_blank\">📖 Vários pacotes e ligações em\nsérie</a>"],
  ["Parte II · Atrasos", "A-E3b", "<b>Ficha 1, Ex. 3 — Em pedaços.</b> A Alice envia ao Bob um vídeo de 700 MB. Entre os dois há 2 routers e todas as ligações têm 100 Mbps (<i>store-and-forward</i>: cada nó recebe o bloco todo antes de o reenviar).<br><br>(b) Quanto se poupa enviando o ficheiro em pedaços de 1000 Bytes, um atrás do outro?", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>700</mn></mrow><annotation encoding=\"application/x-tex\">L = 700</annotation></semantics></math> MB <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>5</mn><mo>,</mo><mn>6</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 5{,}6 \\times 10^9</annotation></semantics></math> bits; 2 routers, portanto <strong>3 ligações</strong>, todas a <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">R = 100</annotation></semantics></math> Mbps. Ignoram-se propagação, processamento e filas, porque o enunciado não os dá.</p>\n<ul>\n<li>Número de pedaços: <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mo>=</mo><mn>700</mn><mo>×</mo><msup><mn>10</mn><mn>6</mn></msup><mi>/</mi><mn>1000</mn><mo>=</mo><mn>700</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><annotation encoding=\"application/x-tex\">N = 700\\times10^6 / 1000 = 700\\,000</annotation></semantics></math>.</li>\n<li>Transmissão de um pedaço: <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>8000</mn><mi>/</mi><msup><mn>10</mn><mn>8</mn></msup><mo>=</mo><mn>80</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">8000 / 10^8 = 80\\ \\mu s</annotation></semantics></math>.</li>\n</ul>\n<p>Com pedaços as ligações trabalham <strong>em paralelo</strong> (<em>pipelining</em>). Enquanto o router 1 envia o pedaço 1, a Alice já envia o pedaço 2. O último pedaço sai da Alice ao fim de <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N</mi><annotation encoding=\"application/x-tex\">N</annotation></semantics></math> transmissões e ainda tem de atravessar as outras 2 ligações: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi><mo>=</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>N</mi><mo>+</mo><mn>3</mn><mo>−</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>×</mo><mn>80</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>=</mo><mn>700</mn><mspace width=\"0.167em\"></mspace><mn>002</mn><mo>×</mo><mn>80</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>≈</mo><mrow><mn mathvariant=\"bold\">𝟓𝟔</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟎𝟎𝟎𝟐</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">T = (N + 3 - 1)\\times 80\\ \\mu s = 700\\,002 \\times 80\\ \\mu s \\approx \\mathbf{56{,}0002\\text{ s}}</annotation></semantics></math></p>\n<p><strong>Poupança:</strong> <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>168</mn><mo>−</mo><mn>56</mn><mo>,</mo><mn>0002</mn><mo>≈</mo><mrow><mn mathvariant=\"bold\">𝟏𝟏𝟐</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">168 - 56{,}0002 \\approx \\mathbf{112\\text{ s}}</annotation></semantics></math> (fica cerca de 3 vezes mais rápido).</p>\n<p>Intuição: com pedaços pequenos o tempo total é praticamente o de <strong>uma</strong> ligação (<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mi>/</mi><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">L/R</annotation></semantics></math>). As outras duas só somam o tempo de um pedaço cada.</p>\n</div>", "<b>Para lembrar:</b> pedaços: as ligações trabalham em paralelo (pipelining).<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#vários-pacotes-e-ligações-em-série\" target=\"_blank\">📖 Vários pacotes e ligações em\nsérie</a>"],
  ["Parte II · Atrasos", "A-E3c", "<b>Ficha 1, Ex. 3 — Em pedaços.</b> A Alice envia ao Bob um vídeo de 700 MB. Entre os dois há 2 routers e todas as ligações têm 100 Mbps (<i>store-and-forward</i>: cada nó recebe o bloco todo antes de o reenviar).<br><br>(c) Cada pedaço leva um \"envelope\" de 20 Bytes. Volta a calcular os tempos.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><mn>700</mn></mrow><annotation encoding=\"application/x-tex\">L = 700</annotation></semantics></math> MB <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>5</mn><mo>,</mo><mn>6</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup></mrow><annotation encoding=\"application/x-tex\">= 5{,}6 \\times 10^9</annotation></semantics></math> bits; 2 routers, portanto <strong>3 ligações</strong>, todas a <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mn>100</mn></mrow><annotation encoding=\"application/x-tex\">R = 100</annotation></semantics></math> Mbps. Ignoram-se propagação, processamento e filas, porque o enunciado não os dá.</p>\n<p><strong>Sem pedaços (a):</strong> só há um envelope, e o bloco fica com <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5</mn><mo>,</mo><mn>6</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup><mo>+</mo><mn>160</mn></mrow><annotation encoding=\"application/x-tex\">5{,}6\\times10^9 + 160</annotation></semantics></math> bits: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3</mn><mo>×</mo><mfrac><mrow><mn>5</mn><mo>,</mo><mn>6</mn><mo>×</mo><msup><mn>10</mn><mn>9</mn></msup><mo>+</mo><mn>160</mn></mrow><msup><mn>10</mn><mn>8</mn></msup></mfrac><mo>≈</mo><mrow><mn mathvariant=\"bold\">𝟏𝟔𝟖</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟎𝟎𝟎𝟎𝟎𝟓</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">3 \\times \\frac{5{,}6\\times10^9 + 160}{10^8} \\approx \\mathbf{168{,}000005\\text{ s}}</annotation></semantics></math> Na prática não muda nada.</p>\n<p><strong>Com pedaços (b):</strong> cada pedaço passa a ter <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>1020</mn><annotation encoding=\"application/x-tex\">1020</annotation></semantics></math> bytes <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>8160</mn></mrow><annotation encoding=\"application/x-tex\">= 8160</annotation></semantics></math> bits, e demora <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>81</mn><mo>,</mo><mn>6</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi></mrow><annotation encoding=\"application/x-tex\">81{,}6\\ \\mu s</annotation></semantics></math> a transmitir: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T</mi><mo>=</mo><mn>700</mn><mspace width=\"0.167em\"></mspace><mn>002</mn><mo>×</mo><mn>81</mn><mo>,</mo><mn>6</mn><mspace width=\"0.222em\"></mspace><mi>μ</mi><mi>s</mi><mo>≈</mo><mrow><mn mathvariant=\"bold\">𝟓𝟕</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟏𝟐</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">T = 700\\,002 \\times 81{,}6\\ \\mu s \\approx \\mathbf{57{,}12\\text{ s}}</annotation></semantics></math></p>\n<p><strong>Poupança:</strong> <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>168</mn><mo>−</mo><mn>57</mn><mo>,</mo><mn>12</mn><mo>≈</mo><mrow><mn mathvariant=\"bold\">𝟏𝟏𝟎</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟗</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">168 - 57{,}12 \\approx \\mathbf{110{,}9\\text{ s}}</annotation></semantics></math>.</p>\n<p><strong>Comparação com as soluções oficiais</strong> (<code>solucoes_ficha_1.pdf</code>): a resposta oficial da 3(c) é “aprox. 1,12 s”. É o <strong>tempo a mais</strong> que os envelopes custam face à alínea (b): <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>57</mn><mo>,</mo><mn>12</mn><mo>−</mo><mn>56</mn><mo>,</mo><mn>00</mn><mo>=</mo><mn>1</mn><mo>,</mo><mn>12</mn></mrow><annotation encoding=\"application/x-tex\">57{,}12 - 56{,}00 = 1{,}12</annotation></semantics></math> s. É o mesmo resultado visto de outra forma.</p>\n<p>Os envelopes custam cerca de 2% a mais (<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>20</mn><mi>/</mi><mn>1000</mn></mrow><annotation encoding=\"application/x-tex\">20/1000</annotation></semantics></math>), mas o <em>pipelining</em> continua a compensar de longe. Se os pedaços fossem <strong>muito</strong> pequenos (por exemplo, 20 bytes de dados para 20 de envelope), o custo dos cabeçalhos passava a dominar. Há um tamanho de pedaço ótimo.</p>\n</div>", "<b>Para lembrar:</b> o cabeçalho também se transmite.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#vários-pacotes-e-ligações-em-série\" target=\"_blank\">📖 Vários pacotes e ligações em\nsérie</a>"],
  ["Parte II · Atrasos", "A-F23a", "<b>Ficha 2, Ex. 3 — Espere, mas não desespere.</b> Uma máquina de café demora 15 s a tirar um café.<br><br>(a) Se a máquina estiver livre e chegarem 10 pessoas ao mesmo tempo, quanto esperam em média até à sua vez? E no mínimo? E no máximo?", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p>A máquina demora 15 s por café.</p>\n<p>A 1.ª pessoa é servida logo; a 2.ª espera que a 1.ª acabe (15 s); a 3.ª espera 30 s; …; a 10.ª espera <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>9</mn><mo>×</mo><mn>15</mn><mo>=</mo><mn>135</mn></mrow><annotation encoding=\"application/x-tex\">9 \\times 15 = 135</annotation></semantics></math> s. As esperas são <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><mn>15</mn><mo>,</mo><mn>30</mn><mo>,</mo><mi>…</mi><mo>,</mo><mn>135</mn></mrow><annotation encoding=\"application/x-tex\">0, 15, 30, \\dots, 135</annotation></semantics></math> s.</p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mtext mathvariant=\"normal\">média</mtext><mo>=</mo><mfrac><mrow><mn>15</mn><mo>×</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo>+</mo><mn>1</mn><mo>+</mo><mi>…</mi><mo>+</mo><mn>9</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow><mn>10</mn></mfrac><mo>=</mo><mfrac><mrow><mn>15</mn><mo>×</mo><mn>45</mn></mrow><mn>10</mn></mfrac><mo>=</mo><mrow><mn mathvariant=\"bold\">𝟔𝟕</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟓</mn><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"bold\"> 𝐬</mtext></mrow></mrow></mrow><annotation encoding=\"application/x-tex\">\\text{média} = \\frac{15 \\times (0+1+\\dots+9)}{10} = \\frac{15 \\times 45}{10} = \\mathbf{67{,}5\\text{ s}}</annotation></semantics></math></p>\n<p><strong>Mínimo: 0 s</strong> (a primeira). <strong>Máximo: 135 s</strong> (a última).</p>\n<p>(Se se contar até ter o café na mão, soma-se 15 s a cada uma: média 82,5 s, mínimo 15 s, máximo 150 s.) É exatamente o atraso de fila de uma rajada de pacotes que chega a uma ligação vazia: o <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n</mi><annotation encoding=\"application/x-tex\">n</annotation></semantics></math>-ésimo espera <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mspace width=\"0.167em\"></mspace><mi>L</mi><mi>/</mi><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">(n-1)\\,L/R</annotation></semantics></math>.</p>\n</div>", "<b>Para lembrar:</b> o n-ésimo espera (n−1)·L/R.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#intensidade-de-tráfego\" target=\"_blank\">📖 Intensidade de tráfego</a>"],
  ["Parte II · Atrasos", "A-F23c", "<b>Ficha 2, Ex. 3 — Espere, mas não desespere.</b> Uma máquina de café demora 15 s a tirar um café.<br><br>(c) Com chegadas independentes, em média uma a cada 15 s, a espera média cresce sem limite. Porquê?", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p>A máquina demora 15 s por café.</p>\n<p>Em média, a máquina tem exatamente o trabalho que consegue fazer (<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mi>a</mi><mi>/</mi><mi>R</mi><mo>=</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">La/R = 1</annotation></semantics></math>). Mas as chegadas são aleatórias:</p>\n<ul>\n<li>às vezes passa um bocado <strong>sem ninguém</strong>: a máquina fica parada, e esse tempo de serviço <strong>perde-se para sempre</strong> (não se pode “guardar” para depois);</li>\n<li>outras vezes chegam <strong>várias pessoas seguidas</strong>: forma-se fila.</li>\n</ul>\n<p>Para desfazer uma fila, a máquina teria de servir <strong>mais depressa</strong> do que as pessoas chegam durante algum tempo. Com <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mi>a</mi><mi>/</mi><mi>R</mi><mo>=</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">La/R = 1</annotation></semantics></math> <strong>não há folga nenhuma</strong> para isso: em média chega tanto quanto sai. A fila comporta-se como um passeio aleatório sem tendência para voltar a zero, e as suas oscilações vão ficando cada vez maiores com o tempo. Por isso o tempo de espera médio cresce sem limite. É a “explosão do atraso” do resumo: o problema não é a média, é a <strong>variabilidade</strong> com zero margem.</p>\n</div>", "<b>Para lembrar:</b> La/R → 1: sem folga, a fila explode.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#intensidade-de-tráfego\" target=\"_blank\">📖 Intensidade de tráfego</a>"],
  ["Parte II · Atrasos", "A-F22c", "<b>Ficha 2, Ex. 2 — Multiplexagem estatística.</b> Ligação de 1 Mbps; cada utilizador transmite a 100 kbps, mas só 10% do tempo. Com comutação de pacotes, há 35 utilizadores.<br><br>(c) Qual é a probabilidade de exatamente k estarem a transmitir em simultâneo? Calcula para k = 3.", null, -1, "<div class=\"sol-title\">Resolução</div><div class=\"sol-aberta\"><p>Ligação de 1 Mbps; cada utilizador transmite a 100 kbps durante 10% do tempo. Com 35 utilizadores, <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X</mi><annotation encoding=\"application/x-tex\">X</annotation></semantics></math> = número dos que transmitem ao mesmo tempo segue <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X</mi><mo>∼</mo><mtext mathvariant=\"normal\">Bin</mtext><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>35</mn><mo>;</mo><mspace width=\"0.222em\"></mspace><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow><annotation encoding=\"application/x-tex\">X \\sim \\text{Bin}(35;\\ 0{,}1)</annotation></semantics></math>.</p>\n<p>Cada utilizador transmite com probabilidade <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi><mo>=</mo><mn>0</mn><mo>,</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">p = 0{,}1</annotation></semantics></math>, independentemente dos outros: <math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>X</mi><mo>=</mo><mi>k</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mfrac linethickness=\"0\"><mn>35</mn><mi>k</mi></mfrac><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mspace width=\"0.167em\"></mspace><mn>0</mn><mo>,</mo><msup><mn>1</mn><mi>k</mi></msup><mspace width=\"0.167em\"></mspace><mn>0</mn><mo>,</mo><msup><mn>9</mn><mrow><mn>35</mn><mo>−</mo><mi>k</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">P(X = k) = \\binom{35}{k}\\, 0{,}1^{k}\\, 0{,}9^{35-k}</annotation></semantics></math></p>\n<ul>\n<li><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mfrac linethickness=\"0\"><mn>35</mn><mi>k</mi></mfrac><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\binom{35}{k}</annotation></semantics></math>: de quantas maneiras se escolhem <strong>quais</strong> <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k</mi><annotation encoding=\"application/x-tex\">k</annotation></semantics></math> dos 35 estão a transmitir;</li>\n<li><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><msup><mn>1</mn><mi>k</mi></msup></mrow><annotation encoding=\"application/x-tex\">0{,}1^k</annotation></semantics></math>: esses <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k</mi><annotation encoding=\"application/x-tex\">k</annotation></semantics></math> estão todos a transmitir;</li>\n<li><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><msup><mn>9</mn><mrow><mn>35</mn><mo>−</mo><mi>k</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">0{,}9^{35-k}</annotation></semantics></math>: os outros <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>35</mn><mo>−</mo><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">35-k</annotation></semantics></math> estão todos calados.</li>\n</ul>\n<p>Para <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi><mo>=</mo><mn>3</mn></mrow><annotation encoding=\"application/x-tex\">k = 3</annotation></semantics></math>:</p>\n<ul>\n<li><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mfrac linethickness=\"0\"><mn>35</mn><mn>3</mn></mfrac><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>=</mo><mstyle displaystyle=\"true\"><mfrac><mrow><mn>35</mn><mo>×</mo><mn>34</mn><mo>×</mo><mn>33</mn></mrow><mrow><mn>3</mn><mo>×</mo><mn>2</mn><mo>×</mo><mn>1</mn></mrow></mfrac></mstyle><mo>=</mo><mn>6545</mn></mrow><annotation encoding=\"application/x-tex\">\\binom{35}{3} = \\dfrac{35 \\times 34 \\times 33}{3 \\times 2 \\times 1} = 6545</annotation></semantics></math>;</li>\n<li><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><msup><mn>1</mn><mn>3</mn></msup><mo>=</mo><mn>0</mn><mo>,</mo><mn>001</mn></mrow><annotation encoding=\"application/x-tex\">0{,}1^3 = 0{,}001</annotation></semantics></math>;</li>\n<li><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0</mn><mo>,</mo><msup><mn>9</mn><mn>32</mn></msup><mo>≈</mo><mn>0</mn><mo>,</mo><mn>03434</mn></mrow><annotation encoding=\"application/x-tex\">0{,}9^{32} \\approx 0{,}03434</annotation></semantics></math>.</li>\n</ul>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>X</mi><mo>=</mo><mn>3</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>6545</mn><mo>×</mo><mn>0</mn><mo>,</mo><mn>001</mn><mo>×</mo><mn>0</mn><mo>,</mo><mn>03434</mn><mo>≈</mo><mrow><mn mathvariant=\"bold\">𝟎</mn><mo mathvariant=\"bold\">,</mo><mn mathvariant=\"bold\">𝟐𝟐𝟓</mn></mrow></mrow><annotation encoding=\"application/x-tex\">P(X = 3) = 6545 \\times 0{,}001 \\times 0{,}03434 \\approx \\mathbf{0{,}225}</annotation></semantics></math></p>\n<p>(É o valor mais provável: em média estão <math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>35</mn><mo>×</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>=</mo><mn>3</mn><mo>,</mo><mn>5</mn></mrow><annotation encoding=\"application/x-tex\">35 \\times 0{,}1 = 3{,}5</annotation></semantics></math> a transmitir.)</p>\n</div>", "<b>Para lembrar:</b> binomial: C(n,k)·p<sup>k</sup>·(1−p)<sup>n−k</sup>.<br>Se a resolução não chegou, lê a teoria: <a class=\"teoria\" href=\"guia_redes_teste1.html#núcleo-da-rede-core\" target=\"_blank\">📖 Núcleo da rede (core)</a>"],
];
